package kr.tong.sky.backgroundqa;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.time.*;
/** Offline actual-service test: remove the task while its private WebView collects two months. */
public class BackgroundProbe extends Instrumentation {
 SQLiteOpenHelper helper;Activity activity;
 public void onCreate(Bundle state){super.onCreate(state);start();}
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public void onStart(){Bundle result=new Bundle();try{
  waitForIdleSync(); // Application startup (including its one-time migration) must finish before seeding a batch.
  Context context=getTargetContext();Class<?> type=Class.forName("kr.tong.sky.SkyDb",true,context.getClassLoader());var constructor=type.getDeclaredConstructor(Context.class);constructor.setAccessible(true);helper=(SQLiteOpenHelper)constructor.newInstance(context);SQLiteDatabase db=helper.getWritableDatabase();
  YearMonth month=YearMonth.now(ZoneId.of("Asia/Seoul")).plusMonths(2);JSONArray queries=new JSONArray();for(String dest:new String[]{"CDG","FRA"})queries.put(new JSONObject().put("carrier","KE").put("origin","ICN").put("destination",dest).put("month",month.toString()));String key="ICN-background-qa";JSONObject batch=new JSONObject().put("key",key).put("carrier","KE").put("origin","ICN").put("region","유럽").put("queries",queries).put("cursor",0).put("failures",0);db.execSQL("INSERT OR REPLACE INTO batches(k,spec) VALUES(?,?)",new Object[]{key,batch.toString()});
  StringBuilder html=new StringBuilder("<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0}table{table-layout:fixed;width:100%}td{height:30px}.bonus-calendar__icons{padding:0}</style></head><body><div role='dialog' aria-labelledby='modals-travelCalendar-title'><h3 id='modals-travelCalendar-title'>ICN CDG</h3><button id='travelCalendarListBtn'>"+month.getYear()+"년 "+month.getMonthValue()+"월</button><div id='bonusCalendarTableWrapEl'><table class='bonus-calendar__table'><tbody>");for(int n=1;n<=month.lengthOfMonth();n++){if((n-1)%7==0)html.append("<tr>");html.append("<td id='day_"+n+"'><div class='bonus-calendar__day'><span aria-hidden='true'>"+n+"</span><span class='ux-class-icon -no-seat -gray'>좌석 없음</span></div></td>");if(n%7==0)html.append("</tr>");}html.append("</tbody></table></div></div></body></html>");
  Intent open=new Intent().setClassName(context,"kr.tong.sky.CollectActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("batchKey",key).putExtra("shared",false).putExtra("oz",false).putExtra("__fixture",html.toString());activity=startActivitySync(open);
  Class<?> serviceType=Class.forName("kr.tong.sky.CollectionService",true,context.getClassLoader());var active=serviceType.getDeclaredField("active");active.setAccessible(true);long until=SystemClock.elapsedRealtime()+10000;while(active.get(null)==null&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(active.get(null)!=null,"collector starts; state="+context.getSharedPreferences("collection",0).getString("state","none"));
  runOnMainSync(()->{activity.finishAndRemoveTask();});
  waitForIdleSync();Thread.sleep(1000);check(active.get(null)!=null,"service survives task removal");check(activity.isDestroyed()||activity.isFinishing(),"collection activity is closed");
  until=SystemClock.elapsedRealtime()+55000;int count=0;while(SystemClock.elapsedRealtime()<until){try(Cursor rows=db.rawQuery("SELECT COUNT(*) FROM snapshots WHERE k IN (?,?)",new String[]{"ICN-CDG-"+month,"ICN-FRA-"+month})){rows.moveToFirst();count=rows.getInt(0);}if(count==2)break;Thread.sleep(250);}check(count==2,"both calendars saved after task removal; count="+count);
  try(Cursor rows=db.rawQuery("SELECT spec FROM batches WHERE k=?",new String[]{key})){check(rows.moveToFirst(),"batch retained");check(new JSONObject(rows.getString(0)).getInt("cursor")==2,"durable cursor advanced to 2");}
  result.putString("stream","BACKGROUND_PASS: actual KE service saved both calendars after CollectActivity task removal; cursor=2; network disabled\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){error.printStackTrace();result.putString("stream","FAIL: "+error);finish(Activity.RESULT_CANCELED,result);}finally{if(helper!=null)helper.close();}}
}
